// escalationSlot returns the *uint64 for an SLM escalation with the
// given reason label, creating it if absent.
func (rc *RouteCounters) escalationSlot(reason string) *uint64 {
	rc.mu.Lock()
	p, ok := rc.slmEscalations[reason]
