// writeRAGSeries emits the nexus_rag_retrieval_total family.
//
// Hits are emitted as a single unlabelled sample line
// `{hit="true"} N` (issue #486): the proxy never attaches a filename
// label to the Prometheus exposition, so the family contributes one
// hit series regardless of how many distinct source files were
// retrieved. Misses carry a bounded `reason` label
// (empty_store, threshold, embed_error). Output is sorted by key for
// deterministic scrape diffs.
func writeRAGSeries(w io.Writer, name, help string, hits *uint64, misses map[string]*uint64) (int64, error) {
	var total int64
	n, err := fmt.Fprintf(w, "# HELP %s %s\n# TYPE %s counter\n", name, help, name)
	if err != nil {
		return total, err
	}
	total += int64(n)

	// Single hit sample line. We emit it even when hits is zero so the
	// series shape is stable for scrapers; a zero counter line is
	// spec-compliant Prometheus text format.
	hitVal := uint64(0)
	if hits != nil {
		hitVal = atomic.LoadUint64(hits)
	}
	n, err = fmt.Fprintf(w, "%s{hit=%q} %d\n", name, "true", hitVal)
	if err != nil {
		return total + int64(n), err
	}
	total += int64(n)

	keys := make([]string, 0, len(misses))
	for k := range misses {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		v := atomic.LoadUint64(misses[k])
		n, err := fmt.Fprintf(w, "%s{hit=%q,reason=%q} %d\n", name, "false", sanitizeLabel(k), v)
		if err != nil {
			return total + int64(n), err
		}
		total += int64(n)
	}
	return total, nil
}

// writeSLMCacheSeries emits the nexus_slm_cache_hits_total and
// nexus_slm_cache_misses_total counters (issue #206, #352). These track
// the SLM decision cache hit rate so operators can tune the cache
// TTL and diagnose cache ineffectiveness. The hits map may be nil or
// empty; nil is treated as zero. Misses is a single pointer (no labels).
func writeSLMCacheSeries(w io.Writer, hits map[string]*uint64, misses *uint64) (int64, error) {
	var total int64

	n, err := fmt.Fprintf(w, "# HELP nexus_slm_cache_hits_total SLM decision cache hits partitioned by kind (issue #352).\n# TYPE nexus_slm_cache_hits_total counter\n")
	if err != nil {
		return total, err
	}
	total += int64(n)

	// Emit one line per kind label, sorted for determinism.
	keys := make([]string, 0, len(hits))
	for k := range hits {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		v := atomic.LoadUint64(hits[k])
		n, err := fmt.Fprintf(w, "nexus_slm_cache_hits_total{kind=%q} %d\n", k, v)
		if err != nil {
			return total, err
		}
		total += int64(n)
	}

	missesVal := atomic.LoadUint64(misses)
	n, err = fmt.Fprintf(w, "# HELP nexus_slm_cache_misses_total SLM decision cache misses.\n# TYPE nexus_slm_cache_misses_total counter\n")
	if err != nil {
