func (c *SLMCache) Stale() int {
	if c == nil {
		return 0
	}
	c.mu.RLock()
	defer c.mu.RUnlock()
	n := len(c.entries)
	if n == 0 {
		return 0
	}
	now := time.Now()
	stale := 0
	for _, entry := range c.entries {
		if now.Sub(entry.stamp) > c.ttl {
			stale++
		}
	}
	return stale
}
